 if x['id']=='M0821':x.update(reading=plan[1],ink=c['B14']['ink'],crop='crops/second_145_scan017_B14.png',box=b['B14'])
 if x['id']=='M0822':x.update(reading=neg[1],ink=c['B15']['ink'],crop='crops/second_145_scan017_B15.png',box=b['B15'])
 if x['id']=='M0824':x.update(reading=mark[1],ink=c['B20']['ink'],crop='crops/second_145_scan017_B20.png',box=b['B20'])
